insert into ebd.biblia_versiculos (traducao_id, livro_numero, livro, livro_abreviado, capitulo, versiculo, texto)
values
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 4, 10, 'Ouve, filho meu, e recebe minhas palavras; e elas te acrescentarão anos de vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 4, 11, 'Eu te ensino no caminho da sabedoria; [e] te faço andar pelos percursos direitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 4, 12, 'Quando tu andares, teus passos não se estreitarão; e se tu correres, não tropeçarás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 4, 13, 'Toma a correção para si, e não [a] largues; guarda-a, porque ela [é] tua vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 4, 14, 'Não entres pela vereda dos perversos, nem andes pelo caminho dos maus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 4, 15, 'Rejeita-o! Não passes por ele; desvia-te dele, e passa longe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 4, 16, 'Pois eles não dormem se não fizerem o mal; e ficam sem sono, se não fizerem tropeçar [a alguém] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 4, 17, 'Porque comem pão da maldade, e bebem vinho de violências.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 4, 18, 'Mas o caminho dos justos é como a luz brilhante, que vai, e ilumina até o dia [ficar claro] por completo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 4, 19, 'O caminho dos perversos é como a escuridão; não sabem nem em que tropeçam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 4, 20, 'Filho meu, presta atenção às minhas palavras; e ouve as minhas instruções.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 4, 21, 'Não as deixes ficarem longe de teus olhos; guarda-as no meio de teu coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 4, 22, 'Porque são vida para aqueles que as encontram; e saúde para todo o seu corpo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 4, 23, 'Acima de tudo o que se deve guardar, guarda o teu coração; porque dele [procedem] as saídas da vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 4, 24, 'Afasta de ti a perversidade da boca; e põe longe de ti a corrupção dos lábios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 4, 25, 'Teus olhos olhem direito; tuas pálpebras estejam corretas diante de ti.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 4, 26, 'Pondera o curso de teus pés; e todos os teus caminhos sejam bem ordenados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 4, 27, 'Não te desvies nem para a direita, nem para a esquerda; afasta teus pés do mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 5, 1, 'Filho meu, presta atenção à minha sabedoria, inclina teus ouvidos ao meu entendimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 5, 2, 'Para que guardes o bom-senso; e teus lábios conservem o conhecimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 5, 3, 'Porque os lábios da mulher pervertida gotejam mel; e sua boca é mais suave que o azeite.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 5, 4, 'Porém seu fim é mais amargo que o absinto; é afiado como a espada de dois fios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 5, 5, 'Seus pés descem à morte; seus passos conduzem ao Xeol.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 5, 6, 'Para que não ponderes a vereda da vida, os percursos delas são errantes, e tu não os conhecerás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 5, 7, 'E agora, filhos, escutai-me; e não vos desvieis das palavras de minha boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 5, 8, 'Mantenha teu caminho longe dela; e não te aproximes da porta da casa dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 5, 9, 'Para que não dês tua honra a outros, nem teus anos [de vida] aos cruéis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 5, 10, 'Para que estranhos não se fartem de teu poder, e teus trabalhos [não sejam] aproveitados em casa alheia;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 5, 11, 'E gemas em teu fim, quando tua carne e teu corpo estiverem consumidos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 5, 12, 'E digas: Como eu odiei a correção, e meu coração desprezou a repreensão?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 5, 13, 'E não escutei a voz de meus ensinadores, nem ouvi a meus mestres.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 5, 14, 'Quase me achei em todo mal, no meio da congregação e do ajuntamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 5, 15, 'Bebe água de tua [própria] cisterna, e das correntes de teu [próprio] poço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 5, 16, 'Derramar-se-iam por fora tuas fontes, [e] pelas ruas os ribeiros de águas?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 5, 17, 'Sejam somente para ti, e não para os estranhos contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 5, 18, 'Seja bendito o teu manancial, e alegra-te com a mulher de tua juventude.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 5, 19, '[Seja ela] uma cerva amorosa e gazela graciosa; que os seios dela te fartem em todo tempo; e anda pelo caminho do amor dela continuamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 5, 20, 'E por que tu, filho meu, andarias perdido pela estranha, e abraçarias o peito da [mulher] alheia?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 5, 21, 'Pois os caminhos do homem estão perante os olhos do SENHOR; e ele pondera todos os seus percursos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 5, 22, 'O perverso será preso pelas suas [próprias] perversidades; e será detido pelas cordas de seu [próprio] pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 5, 23, 'Ele morrerá pela falta de correção; e andará sem rumo pela grandeza de sua loucura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 6, 1, 'Filho meu, se ficaste fiador por teu próximo, [se] deste tua garantia ao estranho;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 6, 2, '[Se] tu foste capturado pelas palavras de tua [própria] boca, e te prendeste pelas palavras de tua boca,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 6, 3, 'Então faze isto agora, meu filho, e livra-te, pois caíste nas mãos de teu próximo; vai, humilha-te, e insiste exaustivamente ao teu próximo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 6, 4, 'Não dês sono aos teus olhos, nem cochilo às tuas pálpebras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 6, 5, 'Livra-te, como a corça do caçador, como o pássaro do caçador de aves.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 6, 6, 'Vai até a formiga, preguiçoso; olha para os caminhos dela, e sê sábio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 6, 7, 'Ela, [mesmo] não tendo chefe, nem fiscal, nem dominador,'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 6, 8, 'Prepara seu alimento no verão, na ceifa ajunta seu mantimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 6, 9, 'Ó preguiçoso, até quando estarás deitado? Quando te levantarás de teu sono?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 6, 10, 'Um pouco de sono, um pouco de cochilo; um pouco de descanso com as mãos cruzadas;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 6, 11, 'Assim a pobreza virá sobre ti como um assaltante; a necessidade [chegará] a ti como um homem armado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 6, 12, 'O homem mal, o homem injusto, anda com uma boca perversa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 6, 13, 'Ele acena com os olhos, fala com seus pés, aponta com seus dedos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 6, 14, 'Perversidades há em seu coração; todo o tempo ele trama o mal; anda semeando brigas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 6, 15, 'Por isso sua perdição virá repentinamente; subitamente ele será quebrado, e não haverá cura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 6, 16, 'Estas seis coisas o SENHOR odeia; e sete sua alma abomina:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 6, 17, 'Olhos arrogantes, língua mentirosa, e mãos que derramam sangue inocente;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 6, 18, 'O coração que trama planos malignos, pés que se apressam a correr para o mal;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 6, 19, 'A falsa testemunha, que sopra mentiras; e o que semeia brigas entre irmãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 6, 20, 'Filho meu, guarda o mandamento de teu pai; e não abandones a lei de tua mãe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 6, 21, 'Amarra-os continuamente em teu coração; e pendura-os ao teu pescoço.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 6, 22, 'Quando caminhares, [isto] te guiará; quando deitares, [isto] te guardará; quando acordares, [isto] falará contigo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 6, 23, 'Porque o mandamento é uma lâmpada, e a lei é luz; e as repreensões para correção são o caminho da vida;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 6, 24, 'Para te protegerem da mulher má, das lisonjas da língua da estranha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 6, 25, 'Não cobices a formosura dela em teu coração; nem te prenda em seus olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 6, 26, 'Porque pela mulher prostituta [chega-se a pedir] um pedaço de pão; e a mulher de [outro] homem anda à caça de uma alma preciosa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 6, 27, 'Por acaso pode alguém botar fogo em seu peito, sem que suas roupas se queimem?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 6, 28, '[Ou] alguém pode andar sobre as brasas, sem seus pés se arderem?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 6, 29, 'Assim [será] aquele que se deitar com a mulher de seu próximo; não será considerado inocente todo aquele que a tocar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 6, 30, 'Não se despreza ao ladrão, quando furta para saciar sua alma, tendo fome;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 6, 31, 'Mas, [se for] achado, ele pagará sete vezes mais; ele terá que dar todos os bens de sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 6, 32, '[Porém] aquele que adultera com mulher [alheia] tem falta de entendimento; quem faz [isso] destrói sua [própria] alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 6, 33, 'Ele encontrará castigo e desgraça; e sua desonra nunca será apagada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 6, 34, 'Porque ciúmes [são] a fúria do marido, e ele de maneira nenhuma terá misericórdia no dia da vingança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 6, 35, 'Ele não aceitará nenhum pagamento pela culpa; nem consentirá, ainda que aumentes os presentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 7, 1, 'Filho meu, guarda minhas palavras; e deposita em ti meus mandamentos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 7, 2, 'Guarda meus mandamentos, e vive; e minha lei, como as pupilas de teus olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 7, 3, 'Ata-os aos teus dedos; escreve-os na tábua do teu coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 7, 4, 'Dize à sabedoria: Tu és minha irmã; E à prudência chama de parente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 7, 5, 'Para que te guardem da mulher alheia, da estranha, [que] lisonjeia com suas palavras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 7, 6, 'Porque da janela de minha casa, pelas minhas grades eu olhei;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 7, 7, 'E vi entre os simples, prestei atenção entre os jovens, um rapaz que tinha falta de juízo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 7, 8, 'Que estava passando pela rua junto a sua esquina, e seguia o caminho da casa dela;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 7, 9, 'No crepúsculo, ao entardecer do dia, no escurecer da noite e nas trevas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 7, 10, 'E eis que uma mulher lhe [saiu] ao encontro, com roupas de prostituta, e astuta de coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 7, 11, 'Esta era barulhenta e insubordinada; os pés dela não paravam em sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 7, 12, 'De tempos em tempos ela fica fora [de casa] ,nas ruas, espreitando em todos os cantos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 7, 13, 'Então ela o pegou, e o beijou; e com atrevimento em seu rosto, disse-lhe:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 7, 14, 'Sacrifícios pacíficos tenho comigo; hoje paguei meus votos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 7, 15, 'Por isso saí para te encontrar; para buscar apressadamente a tua face, e te achei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 7, 16, 'Já preparei minha cama com cobertas; com tecidos de linho fino do Egito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 7, 17, 'Já perfumei meu leito com mirra, aloés e canela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 7, 18, 'Vem [comigo] ; iremos nos embebedar de paixões até a manhã, e nos alegraremos de amores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 7, 19, 'Porque [meu] marido não está em casa; ele viajou para longe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 7, 20, 'Ele tomou uma bolsa de dinheiro em sua mão; [e só] volta para casa no dia determinado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 7, 21, 'Ela o convenceu com suas muitas palavras sedutoras; com a lisonja de seus lábios ela o persuadiu.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 7, 22, 'Ele foi logo após ela, como o boi vai ao matadouro; e como o louco ao castigo das prisões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 7, 23, 'Até que uma flecha atravesse seu fígado; como a ave que se apressa para a armadilha, e não sabe que está [armada] contra sua vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 7, 24, 'Agora pois, filhos, escutai-me; e prestai atenção às palavras de minha boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 7, 25, 'Que teu coração não se desvie para os caminhos dela, e não andes perdido pelas veredas dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 7, 26, 'Porque ela derrubou muitos feridos; e são muitíssimos os que por ela foram mortos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 7, 27, 'A sua casa é caminho para o Xeol, que desce para as câmaras da morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 8, 1, 'Por acaso a sabedoria não clama, e a inteligência não solta sua voz?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 8, 2, 'Nos lugares mais altos, junto ao caminho, nas encruzilhadas das veredas, ela se põe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 8, 3, 'Ao lado das portas, à entrada da cidade; na entrada dos portões, ela grita:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 8, 4, 'Varões, eu vos clamo; [dirijo] minha voz aos filhos dos homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 8, 5, 'Vós que sois ingênuos, entendei a prudência; e vós que sois loucos, entendei [de] coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 8, 6, 'Ouvi, porque falarei coisas nobres; e abro meus lábios para a justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 8, 7, 'Porque minha boca declarará a verdade; e meus lábios abominam a maldade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 8, 8, 'Todas as coisas que digo com minha boca são justas; não há nelas coisa alguma [que seja] distorcida ou perversa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 8, 9, 'Todas elas são corretas para aquele que as entende; e justas para os que encontram conhecimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 8, 10, 'Aceitai minha correção, e não prata; e o conhecimento mais que o ouro fino escolhido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 8, 11, 'Porque a sabedoria é melhor do que rubis; e todas as coisas desejáveis nem sequer podem ser comparadas a ela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 8, 12, 'Eu, a Sabedoria, moro com a Prudência; e tenho o conhecimento do conselho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 8, 13, 'O temor ao SENHOR é odiar o mal: a soberba e a arrogância, o mal caminho e a boca perversa, eu [os] odeio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 8, 14, 'A mim pertence o conselho e a verdadeira sabedoria; eu [tenho] prudência e poder.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 8, 15, 'Por meio de mim os reis governam, e os príncipes decretam justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 8, 16, 'Por meio de mim os governantes dominam; e autoridades, todos os juízes justos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 8, 17, 'Eu amo os que me amam; e os que me buscam intensamente me acharão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 8, 18, 'Bens e honra estão comigo; [assim como] a riqueza duradoura e a justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 8, 19, 'Meu fruto é melhor que o ouro, melhor que o ouro refinado; e meus produtos melhores que a prata escolhida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 8, 20, 'Eu faço andar pelo caminho da justiça, no meio das veredas do juízo;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 8, 21, 'Para eu dar herança aos que me amam, e encher seus tesouros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 8, 22, 'O SENHOR me adquiriu no princípio de seu caminho; desde antes de suas obras antigas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 8, 23, 'Desde a eternidade eu fui ungida; desde o princípio; desde antes do surgimento da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 8, 24, 'Quando ainda não havia abismos, eu fui gerada; quando ainda não havia fontes providas de muitas águas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 8, 25, 'Antes que os montes fossem firmados; antes dos morros, eu fui gerada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 8, 26, 'Quando ele ainda não tinha feito a terra, nem os campos; nem o princípio da poeira do mundo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 8, 27, 'Quando preparava os céus, ali eu estava; quando ele desenhava ao redor da face do abismo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 8, 28, 'Quando firmava as nuvens de cima, quando fortificava as fontes do abismo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 8, 29, 'Quando colocava ao mar o seu limite, para que as águas não ultrapassassem seu mandado; quando estabelecia os fundamentos da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 8, 30, 'Então eu estava com ele como um pupilo; e eu era seu agrado a cada dia, alegrando perante ele em todo tempo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 8, 31, 'Alegrando na habitação de sua terra; e [concedendo] meus agrados aos filhos dos homens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 8, 32, 'Portanto agora, filhos, ouvi-me; porque bem-aventurados serão [os que] guardarem meus caminhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 8, 33, 'Ouvi a correção, e sede sábios; e não a rejeiteis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 8, 34, 'Bem-aventurado [é] o homem que me ouve; que vigia em minhas portas diariamente, que guarda as ombreiras de minhas entradas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 8, 35, 'Porque aquele que me encontrar, encontrará a vida; e obterá o favor do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 8, 36, 'Mas aquele que pecar contra mim fará violência à sua [própria] alma; todos os que me odeiam amam a morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 9, 1, 'A verdadeira sabedoria edificou sua casa; ela lavrou suas sete colunas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 9, 2, 'Ela sacrificou seu sacrifício, misturou seu vinho, e preparou sua mesa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 9, 3, 'Mandou suas servas, [e] está convidando desde os pontos mais altos da cidade, dizendo:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 9, 4, 'Qualquer um que for ingênuo, venha aqui.Aos que têm falta de entendimento, ela diz:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 9, 5, 'Vinde, comei do meu pão; e bebei do vinho que misturei.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 9, 6, 'Abandonai a tolice; e vivei; e andai pelo caminho da prudência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 9, 7, 'Aquele que repreende ao zombador, toma desonra para si mesmo; e o que tenta corrigir ao perverso acaba sendo manchado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 9, 8, 'Não repreendas ao zombador, para que ele não te odeie; repreende ao sábio, e ele te amará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 9, 9, 'Ensina ao sábio, e ele será mais sábio ainda; instrui ao justo, e ele aumentará seu conhecimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 9, 10, 'O temor ao SENHOR é o princípio da sabedoria; e o conhecimento dos santos [é] a prudência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 9, 11, 'Porque por mim teus dias serão multiplicados; e anos de vida a ti serão aumentados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 9, 12, 'Se fores sábio, serás sábio para ti; e se fores zombador, somente tu aguentarás.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 9, 13, 'A mulher louca é causadora de tumultos; [ela é] tola, e não sabe coisa alguma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 9, 14, 'E se senta à porta de sua casa, sobre uma cadeira, nos lugares altos da cidade;'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 9, 15, 'Para chamar aos que passam pelo caminho, e passam por suas veredas, [dizendo] :'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 9, 16, 'Qualquer um que for ingênuo, venha aqui! E aos que tem falta de entendimento, ela diz:'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 9, 17, 'As águas roubadas são doces; e o pão escondido é agradável.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 9, 18, 'Porém não sabem que ali estão os mortos; seus convidados estão nas profundezas do Xeol.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 10, 1, 'Provérbios de Salomão:O filho sábio alegra ao pai; mas o filho tolo é tristeza para sua mãe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 10, 2, 'Tesouros da perversidade para nada aproveitam; porém a justiça livra da morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 10, 3, 'O SENHOR não permite a alma do justo passar fome, porém arruína o interesse dos perversos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 10, 4, 'Aquele que trabalha com mão preguiçosa empobrece; mas a mão de quem trabalha com empenho enriquece.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 10, 5, 'Aquele que ajunta no verão é filho prudente; [mas] o que dorme na ceifa é filho causador de vergonha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 10, 6, 'Há bênçãos sobre a cabeça dos justos; mas a violência cobre a boca dos perversos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 10, 7, 'A lembrança do justo [será] uma bênção; mas o nome dos perversos apodrecerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 10, 8, 'O sábio de coração aceita os mandamentos; mas o louco de lábios será derrubado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 10, 9, 'Aquele que anda em sinceridade anda seguro; mas o que perverte seus caminhos será conhecido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 10, 10, 'Aquele que pisca os olhos maliciosamente gera dores; e o louco de lábios será derrubado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 10, 11, 'A boca do justo é um manancial de vida; mas a boca dos perversos está coberta de violência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 10, 12, 'O ódio desperta brigas; mas o amor cobre todas as transgressões.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 10, 13, 'Nos lábios do bom entendedor se acha sabedoria, mas uma vara está às costas daquele que não tem entendimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 10, 14, 'Os sábios guardam consigo sabedoria; mas a boca do tolo [está] perto da perturbação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 10, 15, 'A prosperidade do rico é a sua cidade fortificada; a pobreza dos necessitados é sua perturbação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 10, 16, 'A obra do justo é para a vida; os frutos do perverso, para o pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 10, 17, 'O caminho para a vida [é d] aquele que guarda a correção; mas aquele que abandona a repreensão anda sem rumo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 10, 18, 'Aquele que esconde o ódio [tem] lábios mentirosos; e o que produz má fama é tolo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 10, 19, 'Na abundância de palavras não há falta de transgressão; mas aquele que refreia seus lábios é prudente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 10, 20, 'A língua do justo [é como] prata escolhida; o coração dos perversos [vale] pouco.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 10, 21, 'Os lábios dos justo apascentam a muitos; mas os tolos, por falta de entendimento, morrem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 10, 22, 'É a bênção do SENHOR que enriquece; e ele não lhe acrescenta dores.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 10, 23, 'Para o tolo, fazer o mal é uma diversão; mas para o homem bom entendedor, [divertida é] a sabedoria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 10, 24, 'O temor do perverso virá sobre ele, mas o desejo dos justos será concedido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 10, 25, 'Assim como o vento passa, assim também o perverso não [mais] existirá; mas o justo [tem] um alicerce eterno.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 10, 26, 'Assim como vinagre para os dentes, e como fumaça para os olhos, assim também é o preguiçoso para aqueles que o mandam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 10, 27, 'O temor ao SENHOR faz aumentar os dias; mas os anos dos perversos serão encurtados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 10, 28, 'A esperança dos justos [é] alegria; mas a expectativa dos perversos perecerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 10, 29, 'O caminho do SENHOR é fortaleza para os corretos, mas ruína para os que praticam maldade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 10, 30, 'O justo nunca será removido, mas os perversos não habitarão a terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 10, 31, 'A boca do justo produz sabedoria, mas a língua perversa será cortada fora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 10, 32, 'Os lábios do justo sabem o que é agradável; mas a boca dos perversos [é cheia] de perversidades.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 11, 1, 'A balança enganosa [é] abominação ao SENHOR; mas o peso justo [é] seu prazer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 11, 2, 'Quando vem a arrogância, vem também a desonra; mas com os humildes [está] a sabedoria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 11, 3, 'A integridade dos corretos os guia; mas a perversidade dos enganadores os destruirá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 11, 4, 'Nenhum proveito terá a riqueza no dia da ira; mas a justiça livrará da morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 11, 5, 'A justiça do íntegro endireitará seu caminho; mas o perverso cairá por sua perversidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 11, 6, 'A justiça dos corretos os livrará; mas os transgressores serão presos em sua própria perversidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 11, 7, 'Quando o homem mau morre, sua expectativa morre; e a esperança de seu poder perece.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 11, 8, 'O justo é livrado da angústia; e o perverso vem em seu lugar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 11, 9, 'O hipócrita com a boca prejudica ao seu próximo; mas os justos por meio do conhecimento são livrados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 11, 10, 'No bem dos justos, a cidade se alegra muito; e quando os perversos perecem, há alegria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 11, 11, 'Pelo bênção dos sinceros a cidade se exalta; mas pela boca dos perversos ela se destrói.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 11, 12, 'Aquele que não tem entendimento despreza a seu próximo; mas o homem bom entendedor se mantêm calado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 11, 13, 'Aquele que conta fofocas revela o segredo; mas o fiel de espírito encobre o assunto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 11, 14, 'Quando não há conselhos sábios, o povo cai; mas na abundância de bons conselheiros [consiste] o livramento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 11, 15, 'Certamente aquele que se tornar fiador de algum estranho passará por sofrimento; mas aquele odeia firmar compromissos [ficará] seguro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 11, 16, 'A mulher graciosa guarda a honra, assim como os violentos guardam as riquezas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 11, 17, 'O homem bondoso faz bem à sua alma; mas o cruel atormenta sua [própria] carne.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 11, 18, 'O perverso recebe falso pagamento; mas aquele que semeia justiça [terá] uma recompensa fiel.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 11, 19, 'Assim como a justiça [leva] para a vida; assim também aquele que segue o mal [é levado] para sua [própria] morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 11, 20, 'O SENHOR abomina os perversos de coração; porém ele se agrada que caminham com sinceridade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 11, 21, 'Com certeza o mal não será absolvido; mas a semente dos justos escapará livre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 11, 22, 'A mulher bela mas sem discrição é como uma joia no focinho de uma porca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 11, 23, 'O desejo dos justos é somente para o bem; mas a esperança dos perversos é a fúria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 11, 24, 'Há quem dá generosamente e tem cada vez mais; e há quem retém mais do que é justo e empobrece.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 11, 25, 'A alma generosa prosperará, e aquele que saciar também será saciado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 11, 26, 'O povo amaldiçoa ao que retém o trigo; mas bênção haverá sobre a cabeça daquele que [o] vende.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 11, 27, 'Aquele que com empenho busca o bem, busca favor; porém o que procura o mal, sobre ele isso lhe virá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 11, 28, 'Aquele que confia em suas riquezas cairá; mas os justos florescerão como as folhas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 11, 29, 'Aquele que perturba sua [própria] casa herdará vento; e o tolo será servo do sábio de coração.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 11, 30, 'O fruto do justo é uma árvore de vida; e o que ganha almas é sábio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 11, 31, 'Ora, se o justo recebe seu pagamento na terra, quanto mais o perverso e o pecador!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 12, 1, 'Aquele que ama a correção ama o conhecimento; mas aquele que odeia a repreensão é um bruto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 12, 2, 'O homem de bem ganha o favor do SENHOR; mas ao homem de pensamentos perversos, ele o condenará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 12, 3, 'O homem não prevalecerá pela perversidade; mas a raiz dos justos não será removida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 12, 4, 'A mulher virtuosa é a coroa de seu marido; mas a causadora de vergonha é como uma podridão em seus ossos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 12, 5, 'Os pensamentos dos justos são de bom juízo; [mas] os conselhos dos perversos são enganosos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 12, 6, 'As palavras dos perversos são para espreitar [o derramamento de] sangue [de inocentes] ; mas a boca dos corretos os livrará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 12, 7, 'Os perversos serão transtornados, e não existirão [mais] ; porém a casa dos justos permanecerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 12, 8, 'Cada um será elogiado conforme seu entendimento; mas o perverso de coração será desprezado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 12, 9, 'Melhor é o que estima pouco a si mesmo mas tem quem o sirva, do que aquele que elogia e si mesmo, mas nem sequer tem pão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 12, 10, 'O justo dá atenção à vida de seus animais; mas [até] as misericórdias dos perversos são cruéis.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 12, 11, 'Aquele que lavra sua terra se saciará de pão; mas o que segue [coisas] inúteis tem falta de juízo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 12, 12, 'O perverso deseja armadilhas malignas; porém a raiz dos justos produzirá [seu fruto] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 12, 13, 'O perverso é capturado pela transgressão de seus lábios, mas o justo sairá da angústia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 12, 14, 'Cada um se sacia do bem pelo fruto de sua [própria] boca; e a recompensa das mãos do homem lhe será entregue de volta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 12, 15, 'O caminho do tolo é correto aos seus [próprios] olhos; mas aquele que ouve o [bom] conselho é sábio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 12, 16, 'A ira do tolo é conhecida no mesmo dia, mas o prudente ignora o insulto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 12, 17, 'Aquele que fala a verdade conta a justiça; porém a testemunha falsa [conta] o engano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 12, 18, 'Há [alguns] que falam [palavras] como que golpes de espada; porém a língua do sábios é [como] um remédio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 12, 19, 'O lábio da verdade ficará para sempre, mas a língua da falsidade [dura] por [apenas] um momento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 12, 20, '[Há] engano no coração dos que tramam o mal; mas os que aconselham a paz [têm] alegria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 12, 21, 'Nenhuma adversidade sobrevirá ao justos; mas os perversos se encherão de mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 12, 22, 'Os lábios mentirosos são abomináveis ao SENHOR, mas dos que falam a verdade são seu prazer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 12, 23, 'O homem prudente é discreto em conhecimento; mas o coração dos tolos proclama a loucura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 12, 24, 'A mão dos que trabalham com empenho dominará, e os preguiçosos se tornarão escravos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 12, 25, 'A ansiedade no coração do homem o abate; [mas] uma boa palavra o alegra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 12, 26, 'O justo age cuidadosamente para com seu próximo, mas o caminho dos perversos os faz errar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 12, 27, 'O preguiçoso não assa aquilo que caçou, mas a riqueza de quem trabalha com empenho [lhe é] preciosa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 12, 28, 'Na vereda da justiça está a vida; e [no] caminho de seu percurso não há morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 13, 1, 'O filho sábio [ouve] a correção do pai; mas o zombador não escuta a repreensão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 13, 2, 'Cada um comerá do bem pelo fruto de sua boca, mas a alma dos infiéis [deseja] a violência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 13, 3, 'Quem toma cuidado com sua boca preserva sua alma; mas aquele que abre muito seus lábios será arruinado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 13, 4, 'A alma do preguiçoso deseja, mas nada [consegue] ; porém a alma dos trabalham com empenho prosperará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 13, 5, 'O justo odeia a palavra mentirosa, mas o perverso age de forma repugnante e vergonhosa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 13, 6, 'A justiça guarda aquele que tem um caminho íntegro; mas a perversidade transtornará ao pecador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 13, 7, 'Há [alguns] que fingem ser ricos, mesmo nada tendo; e [outros] que fingem ser pobres, mesmo tendo muitos bens.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 13, 8, 'O resgate da vida de cada um são suas riquezas; mas o pobre não ouve ameaças.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 13, 9, 'A luz dos justos se alegra, mas a lâmpada dos perversos se apagará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 13, 10, 'A arrogância só produz brigas; mas com os que aceitam conselhos [está] a sabedoria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 13, 11, 'A riqueza [ganha] sem esforço será perdida; mas aquele que a obtém pelas próprias mãos terá cada vez mais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 13, 12, 'A esperança que demora enfraquece o coração, mas o desejo cumprido é [como] uma árvore de vida.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 13, 13, 'Quem despreza a [boa] palavra perecerá; mas aquele que teme ao mandamento será recompensado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 13, 14, 'A doutrina do sábio é manancial de vida, para se desviar das ciladas da morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 13, 15, 'O bom entendimento alcança o favor, mas o caminho dos infiéis é áspero.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 13, 16, 'Todo prudente age com conhecimento, mas o tolo espalha sua loucura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 13, 17, 'O mensageiro perverso cai no mal, mas o representante fiel é [como] um remédio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 13, 18, '[Haverá] pobreza e vergonha ao que rejeita a correção; mas aquele que atende à repreensão será honrado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 13, 19, 'O desejo realizado agrada a alma, mas os tolos abominam se afastar do mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 13, 20, 'Quem anda com os sábios se torna sábio; mas aquele que acompanha os tolos sofrerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 13, 21, 'O mal perseguirá os pecadores, mas os justos serão recompensados com o bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 13, 22, 'O homem de bem deixará herança aos filhos de seus filhos; mas a riqueza do pecador está reservada para o justo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 13, 23, 'A lavoura dos pobres [gera] muita comida; mas há [alguns] que se destroem por falta de juízo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 13, 24, 'Aquele que retém sua vara odeia a seu filho; porém aquele que o ama, desde cedo o castiga.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 13, 25, 'O justo come até sua alma estar saciada; mas o ventre dos perversos passará por necessidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 14, 1, 'Toda mulher sábia edifica sua casa; porém a tola a derruba com suas mãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 14, 2, 'Aquele que anda corretamente teme ao SENHOR; mas o que se desvia de seus caminhos o despreza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 14, 3, 'Na boca do tolo está a vara da arrogância, porém os lábios dos sábios os protegem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 14, 4, 'Não havendo bois, o celeiro fica limpo; mas pela força do boi há uma colheita abundante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 14, 5, 'A testemunha verdadeira não mentirá, mas a testemunha falsa declara mentiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 14, 6, 'O zombador busca sabedoria, mas não [acha] nenhuma; mas o conhecimento é fácil para o prudente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 14, 7, 'Afasta-te do homem tolo, porque [nele] não encontrarás lábios inteligentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 14, 8, 'A sabedoria do prudente é entender seu caminho; mas a loucura dos tolos é engano.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 14, 9, 'Os tolos zombam da culpa, mas entre os corretos está o favor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 14, 10, 'O coração conhece sua [própria] amargura, e o estranho não pode partilhar sua alegria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 14, 11, 'A casa dos perversos será destruída, mas a tenda dos corretos florescerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 14, 12, 'Há um caminho que [parece] correto para o homem, porém o fim dele são caminhos de morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 14, 13, 'Até no riso o coração terá dor, e o fim da alegria é a tristeza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 14, 14, 'Quem se desvia de coração será cheio de seus próprios caminhos, porém o homem de bem [será recompensado] pelos seus.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 14, 15, 'O ingênuo crê em toda palavra, mas o prudente pensa cuidadosamente sobre seus passos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 14, 16, 'O sábio teme, e se afasta do mal; porém o tolo se precipita e se acha seguro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 14, 17, 'Quem se ira rapidamente faz loucuras, e o homem de maus pensamentos será odiado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 14, 18, 'Os ingênuos herdarão a tolice, mas os prudentes serão coroados [com] o conhecimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 14, 19, 'Os maus se inclinarão perante a face dos bons, e os perversos diante das portas do justo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 14, 20, 'O pobre é odiado até pelo seu próximo, porém os amigos dos ricos são muitos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 14, 21, 'Quem despreza a seu próximo, peca; mas aquele que demonstra misericórdia aos humildes [é] bem-aventurado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 14, 22, 'Por acaso não andam errados os que tramam o mal? Mas [há] bondade e fidelidade para os que planejam o bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 14, 23, 'Em todo trabalho cansativo há proveito, mas o falar dos lábios só [leva] à pobreza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 14, 24, 'A coroa dos sábios é a sua riqueza; a loucura dos tolos é loucura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 14, 25, 'A testemunha verdadeira livra almas, mas aquele que declara mentiras é enganador.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 14, 26, 'No temor ao SENHOR [há] forte confiança; e será refúgio para seus filhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 14, 27, 'O temor ao SENHOR é manancial de vida, para se desviar dos laços da morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 14, 28, 'Na multidão do povo está a honra do rei, mas a falta de gente é a ruína do príncipe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 14, 29, 'Quem demora para se irar tem muito entendimento, mas aquele de espírito impetuoso exalta a loucura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 14, 30, 'O coração em paz é vida para o corpo, mas a inveja é [como] podridão nos ossos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 14, 31, 'Quem oprime ao pobre insulta ao seu Criador; mas aquele que mostra compaixão ao necessitado o honra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 14, 32, 'Por sua malícia, o perverso é excluído; porém o justo [até] em sua morte mantém a confiança.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 14, 33, 'No coração do prudente repousa a sabedoria; mas ela será conhecida até entre os tolos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 14, 34, 'A justiça exalta a nação, mas o pecado é a desgraça dos povos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 14, 35, 'O rei se agrada do seu servo prudente; porém ele mostrará seu furor ao causador de vergonha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 15, 1, 'A resposta suave desvia o furor, mas a palavra pesada faz a ira aumentar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 15, 2, 'A língua dos sábios faz bom uso da sabedoria, mas a boca dos tolos derrama loucura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 15, 3, 'Os olhos do SENHOR estão em todo lugar, observando os maus e os bons.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 15, 4, 'Uma língua sã é árvore de vida; mas a perversidade nela é faz o espírito em pedaços.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 15, 5, 'O tolo despreza a correção de seu pai; mas aquele que presta atenção à repreensão age com prudência.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 15, 6, '[Na] casa dos justo há um grande tesouro; mas na renda do perverso há perturbação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 15, 7, 'Os lábios dos sábios derramam conhecimento; mas o coração dos tolos não [age] assim.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 15, 8, 'O sacrifício dos perversos é abominável ao SENHOR, mas a oração dos justos é seu agrado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 15, 9, 'Abominável ao SENHOR é o caminho do perverso; porém ele ama ao que segue a justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 15, 10, 'A correção é ruim para aquele que deixa o caminho; e quem odeia a repreensão morrerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 15, 11, 'O Xeol e a perdição estão perante o SENHOR; quanto mais os corações dos filhos dos homens!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 15, 12, 'O zombador não ama quem o repreende, nem se aproximará dos sábios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 15, 13, 'O coração alegre anima o rosto, mas pela dor do coração o espírito se abate.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 15, 14, 'O coração prudente buscará o conhecimento, mas a boca dos tolos se alimentará de loucura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 15, 15, 'Todos os dias do oprimido são maus, mas o coração alegre é [como] um banquete contínuo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 15, 16, 'Melhor é o pouco tendo o temor ao SENHOR, do que um grande tesouro tendo em si inquietação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 15, 17, 'Melhor é a comida de hortaliças tendo amor, do que a de boi cevado tendo em si ódio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 15, 18, 'O homem que fica irritado facilmente gera brigas; mas aquele que demora para se irar apaziguará o confronto.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 15, 19, 'O caminho do preguiçoso é como uma cerca de espinhos; mas a vereda dos corretos é bem aplanada.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 15, 20, 'O filho sábio alegra ao pai, mas o homem tolo despreza a sua mãe.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 15, 21, 'A loucura é alegria para aquele que tem falta de prudência; mas o homem de bom entendimento andará corretamente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 15, 22, 'Os planos fracassam quando não há [bom] conselho; mas com abundância de conselheiros eles se confirmam.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 15, 23, 'O homem se alegra com a resposta de sua boca; e como é boa a palavra a seu devido tempo!'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 15, 24, 'Para o prudente, o caminho da vida [é] para cima, para que se afaste do Xeol, que é para baixo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 15, 25, 'O SENHOR destruirá a casa dos arrogantes, mas confirmará os limites do terreno da viúva.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 15, 26, 'Os pensamentos do mau são abomináveis ao SENHOR, mas ele se agrada das palavras dos puros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 15, 27, 'Quem pratica a ganância perturba sua [própria] casa; mas quem odeia subornos viverá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 15, 28, 'O coração do justo pensa bem naquilo que vai responder, mas a boca dos perversos derrama maldades em abundância.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 15, 29, 'Longe está o SENHOR dos perversos, mas ele escuta a oração dos justos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 15, 30, 'A luz dos olhos alegra o coração; a boa notícia fortalece os ossos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 15, 31, 'Os ouvidos que escutam a repreensão da vida habitarão entre os sábios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 15, 32, 'Quem rejeita correção menospreza sua [própria] alma; mas aquele que escuta a repreensão adquire entendimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 15, 33, 'O temor ao SENHOR corrige sabiamente; e antes da honra [vem] a humildade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 16, 1, 'Do homem são os planejamentos do coração, mas a reposta da boca [vem] do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 16, 2, 'Todos os caminhos do homem são puros aos seus [próprios] olhos; mas o SENHOR pesa os espíritos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 16, 3, 'Confia tuas obras ao SENHOR, e teus pensamentos serão firmados.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 16, 4, 'O SENHOR fez tudo para seu propósito; e até ao perverso para o dia do mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 16, 5, 'O SENHOR abomina todo orgulhoso de coração; certamente não ficará impune.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 16, 6, 'Com misericórdia e fidelidade a perversidade é reconciliada; e com o temor ao SENHOR se desvia do mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 16, 7, 'Quando os caminhos do homem são agradáveis ao SENHOR, ele faz até seus inimigos terem paz com ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 16, 8, 'Melhor é o pouco com justiça, do que a abundância de rendas com injustiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 16, 9, 'O coração do homem planeja seu caminho, mas é o SENHOR que dirige seus passos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 16, 10, 'Nos lábios do rei estão palavras sublimes; sua boca não transgride quando julga.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 16, 11, 'O peso e a balança justos pertencem ao SENHOR; a ele pertencem todos os pesos da bolsa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 16, 12, 'Os reis abominam fazer perversidade, porque com justiça é que se confirma o trono.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 16, 13, 'Os lábios justos são do agrado dos reis, e eles amam ao que fala palavras direitas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 16, 14, 'A ira do rei é como mensageiros de morte; mas o homem sábio a apaziguará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 16, 15, 'No brilho do rosto do rei há vida; e seu favor é como uma nuvem de chuva tardia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 16, 16, 'Obter sabedoria é tão melhor do que o ouro! E obter sabedoria é mais excelente do que a prata.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 16, 17, 'A estrada dos corretos se afasta do mal; e guarda sua alma quem vigia seu caminho.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 16, 18, 'Antes da destruição vem a arrogância, e antes da queda vem a soberba de espírito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 16, 19, 'É melhor ser humilde de espírito com os mansos, do que repartir despojos com os arrogantes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 16, 20, 'Aquele que pensa prudentemente na palavra encontrará o bem; e quem confia no SENHOR é bem-aventurado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 16, 21, 'O sábio de coração será chamado de prudente; e a doçura dos lábios aumentará a instrução.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 16, 22, 'Manancial de vida é o entendimento, para queles que o possuem; mas a instrução dos tolos é loucura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 16, 23, 'O coração do sábio dá prudência à sua boca; e sobre seus lábios aumentará a instrução.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 16, 24, 'Favo de mel são as palavras suaves: doces para a alma, e remédio para os ossos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 16, 25, 'Há um caminho que parece direito ao homem, porém seu fim são caminhos de morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 16, 26, 'A alma do trabalhador faz ele trabalhar para si, porque sua boca o obriga.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 16, 27, 'O homem maligno cava o mal, e em seus lábios [há] como que um fogo ardente.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 16, 28, 'O homem perverso levanta contenda, e o difamador faz [até] grandes amigos se separarem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 16, 29, 'O homem violento ilude a seu próximo, e o guia por um caminho que não é bom.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 16, 30, 'Ele fecha seus olhos para imaginar perversidades; ele aperta os lábios para praticar o mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 16, 31, 'Cabelos grisalhos são uma coroa de honra, [caso] se encontrem no caminho de justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 16, 32, 'Melhor é o que demora para se irritar do que o valente; e [melhor é] aquele que domina seu espírito do que aquele que toma uma cidade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 16, 33, 'A sorte é lançada no colo, mas toda decisão pertence ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 17, 1, 'Melhor é um pedaço seco de comida com tranquilidade, do que uma casa cheia de carne com briga.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 17, 2, 'O servo prudente dominará o filho causador de vergonha, e receberá parte da herança entre os irmãos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 17, 3, 'O crisol é para a prata, e o forno para o ouro; mas o SENHOR prova os corações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 17, 4, 'O malfeitor presta atenção ao lábio injusto; o mentiroso inclina os ouvidos à língua maligna.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 17, 5, 'Quem ridiculariza o pobre insulta o seu Criador; aquele que se alegra da calamidade não ficará impune.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 17, 6, 'A coroa dos idosos [são] os filhos de seus filhos; e a glória dos filhos são seus pais.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 17, 7, 'Não é adequado ao tolo falar com elegância; muito menos para o príncipe falar mentiras.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 17, 8, 'O presente é [como] uma pedra preciosa aos olhos de seus donos; para onde quer que se voltar, [tentará] ter algum proveito.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 17, 9, 'Quem perdoa a transgressão busca a amizade; mas quem repete o assunto afasta amigos íntimos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 17, 10, 'A repreensão entra mais profundamente no prudente do que cem açoites no tolo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 17, 11, 'Na verdade quem é mal busca somente a rebeldia; mas o mensageiro cruel será enviado contra ele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 17, 12, '[É melhor] ao homem encontrar uma ursa roubada [de seus filhotes] ,do que um tolo em sua loucura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 17, 13, 'Quanto ao que devolve o mal no lugar do bem, o mal nunca se afastará de sua casa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 17, 14, 'Começar uma briga é [como] deixar águas rolarem; por isso, abandona a discussão antes que haja irritação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 17, 15, 'Quem absolve ao perverso e quem condena ao justo, ambos são abomináveis ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 17, 16, 'Para que serve o dinheiro na mão do tolo, já que ele não tem interesse em obter sabedoria?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 17, 17, 'O amigo ama em todo tempo, e o irmão nasce para [ajudar] na angústia.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 17, 18, 'O homem imprudente assume compromisso, ficando como fiador de seu próximo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 17, 19, 'Quem ama a briga, ama a transgressão; quem constrói alta sua porta busca ruína.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 17, 20, 'O perverso de coração nunca encontrará o bem; e quem distorce [as palavras de] sua língua cairá no mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 17, 21, 'Quem gera o louco [cria] sua própria tristeza; e o pai do imprudente não se alegrará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 17, 22, 'O coração alegre é um bom remédio, mas o espírito abatido faz os ossos se secarem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 17, 23, 'O perverso toma o presente do seio, para perverter os caminhos da justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 17, 24, 'A sabedoria está diante do rosto do prudente; porém os olhos do tolo [estão voltados] para os confins da terra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 17, 25, 'O filho tolo é tristeza para seu pai, e amargura para aquela que o gerou.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 17, 26, 'Também não é bom punir ao justo, nem bater nos príncipes por causa da justiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 17, 27, 'Quem entende o conhecimento guarda suas palavras; [e] o homem de bom entendimento [é] de espírito calmo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 17, 28, 'Até o tolo, quando está calado, é considerado como sábio; [e] quem fecha seus lábios, como de bom senso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 18, 1, 'Quem se isola busca seu [próprio] desejo; ele se volta contra toda sabedoria.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 18, 2, 'O tolo não tem prazer no entendimento, mas sim em revelar sua [própria] opinião.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 18, 3, 'Na vinda do perverso, vem também o desprezo; e com a desonra [vem] a vergonha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 18, 4, 'A boca do homem são [como] águas profundas; e o manancial de sabedoria [como] um ribeiro transbordante.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 18, 5, 'Não é bom favorecer ao perverso para prejudicar ao justo num julgamento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 18, 6, 'Os lábios do tolo entram em briga, e sua boca chama pancadas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 18, 7, 'A boca do tolo é sua [própria] destruição, e seus lábios [são] armadilha para sua alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 18, 8, 'As palavras do fofoqueiro são como alimentos deliciosos, que descem até o interior do ventre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 18, 9, 'O preguiçoso em fazer sua obra é irmão do causador de prejuízo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 18, 10, 'O nome do SENHOR é uma torre forte; o justo correrá até ele, e ficará seguro.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 18, 11, 'Os bens do rico são [como] uma cidade fortificada, e como um muro alto em sua imaginação.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 18, 12, 'Antes da ruína o coração humano é orgulhoso; e antes da honra [vem] a humildade.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 18, 13, 'Quem responde antes de ouvir [age] como tolo e causa vergonha para si.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 18, 14, 'O espírito do homem o sustentará quando doente; mas o espírito abatido, quem o levantará?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 18, 15, 'O coração do prudente adquire conhecimento; e o ouvido dos sábios busca conhecimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 18, 16, 'O presente do homem alarga seu caminho, e o leva perante a face dos grandes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 18, 17, 'Aquele que primeiro mostra sua causa [parece ser] justo; mas [somente até] que outro venha, e o investigue.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 18, 18, 'O sorteio cessa disputas, e separa poderosos [de se confrontarem] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 18, 19, 'O irmão ofendido [é mais difícil] que uma cidade fortificada; e as brigas são como ferrolhos de uma fortaleza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 18, 20, 'Do fruto da boca do homem seu ventre se fartará; dos produtos de seus lábios se saciará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 18, 21, 'A morte e a vida estão no poder da língua; e aquele que a ama comerá do fruto dela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 18, 22, 'Quem encontrou esposa, encontrou o bem; e obteve o favor do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 18, 23, 'O pobre fala com súplicas; mas o rico responde com durezas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 18, 24, 'O homem [que tem] amigos pode ser prejudicado [por eles] ; porém há um amigo mais chegado que um irmão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 19, 1, 'Melhor é o pobre que anda em sua honestidade do que o perverso de lábios e tolo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 19, 2, 'E não é bom a alma sem conhecimento; e quem tem pés apressados comete erros.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 19, 3, 'A loucura do homem perverte seu caminho; e seu coração se ira contra o SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 19, 4, 'A riqueza faz ganhar muitos amigos; mas ao pobre, até seu amigo o abandona.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 19, 5, 'A falsa testemunha não ficará impune; e quem fala mentiras não escapará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 19, 6, 'Muitos suplicam perante o príncipe; e todos querem ser amigos daquele que dá presentes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 19, 7, 'Todos os irmãos do pobre o odeiam; ainda mais seus amigos se afastam dele; ele corre atrás deles com palavras, mas eles nada lhe [respondem] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 19, 8, 'Quem adquire entendimento ama sua alma; quem guarda a prudência encontrará o bem.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 19, 9, 'A falsa testemunha não ficará impune; e quem fala mentiras perecerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 19, 10, 'O luxo não é adequado ao tolo; muito menos ao servo dominar sobre príncipes.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 19, 11, 'A prudência do homem retém sua ira; e sua glória é ignorar a ofensa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 19, 12, 'A fúria do rei é como o rugido de um leão; mas seu favor é como orvalho sobre a erva.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 19, 13, 'O filho tolo é uma desgraça ao seu pai; e brigas da esposa são [como] uma goteira duradoura.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 19, 14, 'A casa e as riquezas são a herança dos pais; porém a mulher prudente [vem] do SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 19, 15, 'A preguiça faz cair num sono profundo; e a alma desocupada passará fome.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 19, 16, 'Quem guarda o mandamento cuida de sua alma; e quem despreza seus caminhos morrerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 19, 17, 'Quem faz misericórdia ao pobre empresta ao SENHOR; e ele lhe pagará sua recompensa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 19, 18, 'Castiga a teu filho enquanto há esperança; mas não levantes tua alma para o matar.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 19, 19, 'Aquele que tem grande irá será punido; porque se tu [o] livrares, terás de fazer o mesmo de novo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 19, 20, 'Ouve o conselho, e recebe a disciplina; para que sejas sábio nos teus últimos [dias] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 19, 21, 'Há muitos pensamentos no coração do homem; porém o conselho do SENHOR prevalecerá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 19, 22, 'O que se deseja do homem [é] sua bondade; porém o pobre é melhor do que o homem mentiroso.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 19, 23, 'O temor ao SENHOR [encaminha] para a vida; aquele que [o tem] habitará satisfeito, nem mal algum o visitará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 19, 24, 'O preguiçoso põe sua mão no prato, e nem sequer a leva de volta à boca.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 19, 25, 'Fere ao zombador, e o ingênuo será precavido; e repreende ao prudente, e ele aprenderá conhecimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 19, 26, 'Aquele que prejudica ao pai [ou] afugenta a mãe é filho causador de vergonha e de desgraça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 19, 27, 'Filho meu, deixa de ouvir a instrução, [então] te desviarás das palavras de conhecimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 19, 28, 'A má testemunha escarnece do juízo; e a boca dos perversos engole injustiça.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 19, 29, 'Julgamentos estão preparados para zombadores, e açoites para as costas dos tolos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 20, 1, 'O vinho é zombador, a bebida forte é causadora de alvoroços; e todo aquele que errar por causa deles não é sábio.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 20, 2, 'O temor ao rei é como um rugido de leão; e quem se ira contra ele peca contra sua [própria] alma.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 20, 3, 'É honroso ao homem terminar a disputa; mas todo tolo nela se envolve.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 20, 4, 'O preguiçoso não lavra no inverno; [por isso] ele mendigará durante a ceifa, pois nada terá.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 20, 5, 'O conselho no coração do homem [é como] águas profundas; mas o homem prudente [consegue] tirá-lo para fora.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 20, 6, 'Muitos homens, cada um deles afirma ter bondade; porém o homem fiel, quem o encontrará?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 20, 7, 'O justo caminha em sua integridade; bem-aventurados [serão] seus filhos depois dele.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 20, 8, 'O rei, ao se sentar no trono do juízo, com seus olhos dissipa todo mal.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 20, 9, 'Quem poderá dizer: “Purifiquei meu coração; estou limpo de meu pecado”?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 20, 10, 'Dois pesos e duas medidas, ambos são abominação ao SENHOR.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 20, 11, 'Até o jovem é conhecido pelas suas ações, se sua obra for pura e correta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 20, 12, 'O ouvido que ouve e o olho que vê, o SENHOR os fez ambos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 20, 13, 'Não ames ao sono, para que não empobreças; abre teus olhos, e te fartarás de pão.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 20, 14, '[Preço] ruim, [preço] ruim, diz o comprador; mas quando vai embora, então se gaba.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 20, 15, 'Há ouro, e muitos rubis; mas os lábios do conhecimento são joia preciosa.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 20, 16, 'Toma a roupa daquele que fica por fiador de estranho; toma como penhor daquele [que fica por fiador] da estranha.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 20, 17, 'O pão da mentira é agradável ao homem; mas depois sua boca se encherá de pedregulhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 20, 18, 'Os planos são confirmados por meio do conselho; e com conselhos prudentes faze a guerra.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 20, 19, 'Quem anda fofocando revela segredos; por isso não te envolvas com aquele que fala demais com seus lábios.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 20, 20, 'Aquele que amaldiçoar a seu pai ou a sua mãe terá sua lâmpada apagada em trevas profundas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 20, 21, 'A herança ganha apressadamente no princípio, seu fim não será abençoado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 20, 22, 'Não digas: Devolverei o mal; Espera pelo SENHOR, e ele te livrará.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 20, 23, 'O SENHOR abomina pesos falsificados; e balanças enganosas não são boas.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 20, 24, 'Os passos do homem pertencem ao SENHOR; como, pois, o homem entenderá seu caminho?'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 20, 25, 'Armadilha ao homem é prometer precipitadamente algo como sagrado, e [somente] depois pensar na seriedade dos votos[ que fez] .'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 20, 26, 'O rei sábio espalha os perversos, e os atropela.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 20, 27, 'O espírito humano é uma lâmpada do SENHOR, que examina todo o interior do ventre.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 20, 28, 'A bondade e a fidelidade protegem o rei; e com bondade seu trono é sustentado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 20, 29, 'A beleza dos jovens é sua força; e a honra dos velhos é [seus] cabelos brancos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 20, 30, 'Os golpes das feridas purificam os maus; como também as pancadas no interior do corpo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 21, 1, '[Como] ribeiros de águas é o coração do rei na mão do SENHOR, ele o conduz para onde quer.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 21, 2, 'Todo caminho do homem é correto aos seus [próprios] olhos; mas o SENHOR pesa os corações.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 21, 3, 'Praticar justiça e juízo é mais aceitável ao SENHOR do que sacrifício.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 21, 4, 'Olhos orgulhosos e coração arrogante: a lavoura dos perversos é pecado.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 21, 5, 'Os planos de quem trabalha com empenho somente [levam] à abundância; mas [os de] todo apressado somente à pobreza.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 21, 6, 'Trabalhar [para obter] tesouros com língua mentirosa é algo inútil [e] fácil de se perder; os que [assim fazem] buscam a morte.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 21, 7, 'A violência [praticada] pelos perversos os destruirá, porque se negam a fazer o que é justo.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 21, 8, 'O caminho do homem transgressor [é] problemático; porém a obra do puro é correta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 21, 9, 'É melhor morar num canto do terraço do que numa casa espaçosa com uma mulher briguenta.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 21, 10, 'A alma do perverso deseja o mal; seu próximo não lhe agrada em seus olhos.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 21, 11, 'Castigando ao zombador, o ingênuo se torna sábio; e ensinando ao sábio, ele ganha conhecimento.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 21, 12, 'O justo considera prudentemente a casa do perverso; ele transtorna os perversos para a ruína.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 21, 13, 'Quem tapa seu ouvido ao clamor do pobre, ele também clamará, mas não será ouvido.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 21, 14, 'O presente em segredo extingue a ira; e a dádiva no colo [acalma] o forte furor.'),
((select id from ebd.biblia_traducoes where codigo = 'BLIVRE'), 20, 'Provérbios', 'Pv', 21, 15, 'Alegria para o justo é fazer justiça; mas [isso é] pavor para os que praticam maldade.')
